css:
.po {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);position:relative;display:flex;flex-direction:column;border-radius:var(--radius-lg);border:var(--spacing-hairline) solid var(--color-border-2);background:var(--color-popover);padding:8px;color:var(--color-foreground);box-shadow:var(--sh-overlay);font-size:var(--text-sm)}
:where([data-doop-theme="light"]) .po {--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.po .ar {position:absolute;left:24px;top:-5px;width:10px;height:10px;transform:rotate(45deg);background:var(--color-popover);border-top:var(--spacing-hairline) solid var(--color-border-2);border-left:var(--spacing-hairline) solid var(--color-border-2)}
.po .ct {position:relative}
